contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        string memory s1 = c.symbol();
        string memory s2 = c.symbol();
        bytes memory b = bytes(s1);
        bool validUtf8 = true;
        for (uint i = 0; i < b.length; ) {
            uint8 ch = uint8(b[i]);
            if (ch < 0x80) {
                i += 1;
            } else if ((ch & 0xE0) == 0xC0) {
                if (i + 1 >= b.length) { validUtf8 = false; break; }
                if ((uint8(b[i + 1]) & 0xC0) != 0x80) { validUtf8 = false; break; }
                i += 2;
            } else if ((ch & 0xF0) == 0xE0) {
                if (i + 2 >= b.length) { validUtf8 = false; break; }
                if ((uint8(b[i + 1]) & 0xC0) != 0x80) { validUtf8 = false; break; }
                if ((uint8(b[i + 2]) & 0xC0) != 0x80) { validUtf8 = false; break; }
                i += 3;
            } else if ((ch & 0xF8) == 0xF0) {
                if (i + 3 >= b.length) { validUtf8 = false; break; }
                if ((uint8(b[i + 1]) & 0xC0) != 0x80) { validUtf8 = false; break; }
                if ((uint8(b[i + 2]) & 0xC0) != 0x80) { validUtf8 = false; break; }
                if ((uint8(b[i + 3]) & 0xC0) != 0x80) { validUtf8 = false; break; }
                i += 4;
            } else {
                validUtf8 = false;
                break;
            }
        }
        assert(keccak256(bytes(s1)) == keccak256(bytes(s2)) && validUtf8);
    }

    receive() external payable {}
}

