            // We express the expected returned bool as: the call is expected to succeed
            // (return true) exactly when the spender's allowance was at least value,
            // because the appended sender address is the contract itself, which is the spender.
            expected = c.allowance(from, address(c)) >= value;
        }

        assert(!reverted || returned == expected);
    }

    receive() external payable {}
}

