contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address user, uint256 value, bool authorized) public payable {
        // Make caller either a ward or not, so the precondition on wards is deterministic.
        if (authorized) {
            c.rely(address(this));
        }

        uint256 wardsBefore = c.wards(address(this));
        require(authorized == (wardsBefore == 1), "setup failed");

        bool reverted;
        try c.mint(user, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the auth-gated mint reverts exactly when the caller is not a ward.
        assert(reverted != (wardsBefore == 1));
    }

    receive() external payable {}
}

