contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 value) public {
        // msg.sender for every call on c is address(this), the contract that deployed c,
        // which is a ward only if the constructor relied on it. Compare the actual ward
        // status to decide whether burn must revert.
        uint256 wardStatus = c.wards(address(this));

        bool reverted;
        try c.burn(user, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (wardStatus == 1) {
            assert(!reverted);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

